      if (reqs.some((r) => r.endsWith("_RX"))) L.push(`    SPI_I2S_DMACmd(${id}, SPI_I2S_DMAReq_Rx, ENABLE);`);
      if (reqs.some((r) => r.endsWith("_TX"))) L.push(`    SPI_I2S_DMACmd(${id}, SPI_I2S_DMAReq_Tx, ENABLE);`);
