  L.push(` * \u5382\u5546\uFF1A${dev.vendor}    \u5185\u6838\uFF1A${dev.core}`);
  L.push(` * \u751F\u6210\u5668\uFF1Ageneric\uFF08\u8BE5\u5382\u5546\u8FD8\u6CA1\u6709\u4E13\u7528\u540E\u7AEF\uFF0C\u53EA\u6709\u5F15\u811A\u8868\u4E0E TODO\uFF09`);
  L.push(` * \u751F\u6210\u65F6\u95F4\uFF1A${stamp()}`);
