var KEY = "rfr.recent";
var LIMIT = 8;
function loadRecent() {
  try {
    const raw = JSON.parse(localStorage.getItem(KEY) ?? "[]");
    if (!Array.isArray(raw)) return [];
    return raw.filter((x) => typeof x?.path === "string" && typeof x?.name === "string").sort((a, b) => (b.at ?? 0) - (a.at ?? 0)).slice(0, LIMIT);
  } catch {
    return [];
  }
}
function pushRecent(entry) {
  const list = loadRecent().filter((x) => x.path !== entry.path);
  list.unshift({ ...entry, at: Date.now() });
  const next = list.slice(0, LIMIT);
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
  }
  return next;
}
function clearRecent() {
  try {
    localStorage.removeItem(KEY);
  } catch {
  }
  return [];
}
function dropRecent(path) {
  const next = loadRecent().filter((x) => x.path !== path);
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
  }
  return next;
}
function shortPath(path) {
  const parts = path.split(/[\\/]/);
  if (parts.length <= 2) return path;
  return `\u2026/${parts.slice(-2).join("/")}`;
}

